import json, datetime, re, ast, textwrap

def text_content(c):
    if isinstance(c,str): return c
    if isinstance(c,list):
        outs=[]
        for x in c:
            if isinstance(x,dict):
                outs.append(x.get('text') or x.get('reasoning') or str(x))
            else: outs.append(str(x))
        return '\n'.join(outs)
    return str(c)
for fname in ['/tmp/docent_run_1.json','/tmp/docent_run_2.json']:
    msgs=json.load(open(fname))[0]['transcripts'][0]['messages']
    rows=[]
    for i,m in enumerate(msgs):
        ts=m.get('metadata',{}).get('timestamp') or 0
        c=text_content(m.get('content',''))
        if not c.strip(): continue
        rows.append((ts,i,m.get('role'),c))
    rows.sort(key=lambda x:(x[0],x[1]))
    out=f'/tmp/sorted_{fname.split("_")[-1]}.txt'
    with open(out,'w') as f:
        for ts,i,role,c in rows:
            dt=datetime.datetime.fromtimestamp(ts/1000).strftime('%Y-%m-%d %H:%M:%S.%f')[:-3] if ts else ''
            s=c.replace('\n',' | ')
            if len(s)>1200: s=s[:1200]+'...'
            f.write(f'{dt} idx={i:04d} {role}: {s}\n')
    print(out, len(rows))
